using System.ComponentModel;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Configuration -----------------------------------------------------------

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

const string modelId = "gpt-4o-mini-2024-07-18";

// --- Shared state for the note-taking tool -----------------------------------

var notebook = new ResearchNotebook();

// --- Tool definitions --------------------------------------------------------

var tools = new AITool[]
{
    AIFunctionFactory.Create(
        ([Description("The search query to look up on the web")] string query) =>
        {
            return WebSearchTool.SearchAsync(query);
        },
        name: "web_search",
        description: "Searches the web for the given query and returns a list of result snippets. Use this to find information about a topic."),

    AIFunctionFactory.Create(
        ([Description("A concise heading for this note")] string heading,
         [Description("The content of the note with key facts")] string content) =>
        {
            notebook.AddNote(heading, content);
            return $"Note saved under \"{heading}\". You now have {notebook.Count} note(s).";
        },
        name: "save_note",
        description: "Saves a research note to the notebook. Use this to record important findings from your searches."),

    AIFunctionFactory.Create(
        () =>
        {
            return notebook.GetAllNotes();
        },
        name: "read_notes",
        description: "Reads all saved research notes. Use this to review what you've gathered before writing a summary."),
};

// --- Agent setup -------------------------------------------------------------

var openAiClient = new OpenAIClient(apiKey);
IChatClient chatClient = openAiClient.GetChatClient(modelId).AsIChatClient();

var agent = new ChatClientAgent(
    chatClient: chatClient,
    instructions: """
        You are a research assistant. When given a topic:
        1. Search the web multiple times with different queries to gather diverse information.
        2. Save key findings as notes using the save_note tool.
        3. After gathering enough information (at least 3 searches), read your notes.
        4. Write a well-structured summary with sections and cite your sources.
        Be thorough but concise. Focus on factual, up-to-date information.
        """,
    name: "ResearchAgent",
    description: "An agent that researches topics by searching the web and summarizing findings.",
    tools: tools);

// --- Run the agent -----------------------------------------------------------

Console.WriteLine("╔══════════════════════════════════════════╗");
Console.WriteLine("║       AI Research Agent (GPT-4o-mini)    ║");
Console.WriteLine("╠══════════════════════════════════════════╣");
Console.WriteLine("║  Type a topic to research, or 'quit'.   ║");
Console.WriteLine("╚══════════════════════════════════════════╝");
Console.WriteLine();

while (true)
{
    Console.ForegroundColor = ConsoleColor.Cyan;
    Console.Write("Research topic> ");
    Console.ResetColor();

    var topic = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    Console.WriteLine();
    Console.ForegroundColor = ConsoleColor.DarkGray;
    Console.WriteLine("Researching... (the agent will search the web and take notes)");
    Console.ResetColor();

    notebook.Clear();

    var session = await agent.CreateSessionAsync();
    var options = new AgentRunOptions { ModelMaxOutputTokens = 2048 };

    try
    {
        await foreach (var update in agent.RunStreamingAsync($"Research this topic thoroughly and provide a summary: {topic}", session, options))
        {
            if (update.Message?.Role == ChatRole.Assistant && update.Message.Text is { Length: > 0 } text)
            {
                Console.Write(text);
            }
        }
    }
    catch (Exception ex)
    {
        Console.ForegroundColor = ConsoleColor.Red;
        Console.WriteLine($"\nError: {ex.Message}");
        Console.ResetColor();
    }

    Console.WriteLine();
    Console.WriteLine();
}

Console.WriteLine("Goodbye!");

