/// <summary>
/// Performs web searches using the DuckDuckGo Instant Answer API (no key required).
/// </summary>
static class WebSearchTool
{
    private static readonly HttpClient s_http = new()
    {
        DefaultRequestHeaders =
        {
            { "User-Agent", "ResearchAgent/1.0" },
        },
        Timeout = TimeSpan.FromSeconds(15),
    };

    public static async Task<string> SearchAsync(string query)
    {
        try
        {
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
            var json = await s_http.GetStringAsync(url);

            using var doc = System.Text.Json.JsonDocument.Parse(json);
            var root = doc.RootElement;

            var results = new List<string>();

            // Abstract (main answer)
            if (root.TryGetProperty("Abstract", out var abs) && abs.GetString() is { Length: > 0 } abstractText)
            {
                var source = root.TryGetProperty("AbstractSource", out var src) ? src.GetString() : "Unknown";
                var absUrl = root.TryGetProperty("AbstractURL", out var au) ? au.GetString() : "";
                results.Add($"[{source}] {abstractText} ({absUrl})");
            }

            // Related topics
            if (root.TryGetProperty("RelatedTopics", out var topics) && topics.ValueKind == System.Text.Json.JsonValueKind.Array)
            {
                foreach (var topic in topics.EnumerateArray().Take(5))
                {
                    if (topic.TryGetProperty("Text", out var text) && text.GetString() is { Length: > 0 } t)
                    {
                        var firstUrl = topic.TryGetProperty("FirstURL", out var fu) ? fu.GetString() : "";
                        results.Add($"- {t} ({firstUrl})");
                    }
                }
            }

            // Infobox
            if (root.TryGetProperty("Infobox", out var infobox) &&
                infobox.ValueKind == System.Text.Json.JsonValueKind.Object &&
                infobox.TryGetProperty("content", out var infoContent) &&
                infoContent.ValueKind == System.Text.Json.JsonValueKind.Array)
            {
                foreach (var item in infoContent.EnumerateArray().Take(5))
                {
                    if (item.TryGetProperty("label", out var label) &&
                        item.TryGetProperty("value", out var value))
                    {
                        results.Add($"- {label.GetString()}: {value.GetString()}");
                    }
                }
            }

            if (results.Count == 0)
                return $"No detailed results found for '{query}'. Try a more specific or different query.";

            return $"Search results for '{query}':\n{string.Join("\n", results)}";
        }
        catch (Exception ex)
        {
            return $"Search failed for '{query}': {ex.Message}. Try a different query.";
        }
    }
}

/// <summary>
/// Thread-safe in-memory notebook for storing research notes.
/// </summary>
sealed class ResearchNotebook
{
    private readonly List<(string Heading, string Content)> _notes = [];
    private readonly Lock _lock = new();

    public int Count
    {
        get { lock (_lock) return _notes.Count; }
    }

    public void AddNote(string heading, string content)
    {
        lock (_lock) _notes.Add((heading, content));
    }

    public string GetAllNotes()
    {
        lock (_lock)
        {
            if (_notes.Count == 0)
                return "Notebook is empty. Search for information first.";

            return string.Join("\n\n", _notes.Select((n, i) =>
                $"--- Note {i + 1}: {n.Heading} ---\n{n.Content}"));
        }
    }

    public void Clear()
    {
        lock (_lock) _notes.Clear();
    }
}

